@namespace sv_e0a9608232cf4e858fc3679f81403fff.Components.Pages.Settings
@using sv_e0a9608232cf4e858fc3679f81403fff.Models

@if (_loading)
{
    <div class="text-center py-5"><div class="spinner-border" role="status"></div></div>
}
else
{
    <div>
        <h4 class="mb-4">Appearance</h4>

        @if (_statusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_statusMessage
                <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-6">
                <!-- Theme -->
                <div class="card mb-3">
                    <div class="card-header fw-semibold">Theme</div>
                    <div class="card-body">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")"
                                       value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="card mb-3">
                    <div class="card-header fw-semibold">Font Size</div>
                    <div class="card-body">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")"
                                       value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="mb-3">
                    <label class="form-label fw-semibold">Language</label>
                    <select class="form-select" @bind="_language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                        <option value="Chinese">Chinese</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <!-- Live Preview -->
            <div class="col-md-6">
                <div class="card">
                    <div class="card-header fw-semibold">Live Preview</div>
                    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h5 style="@GetPreviewFontStyle()">Preview Title</h5>
                        <p style="@GetPreviewFontStyle()" class="@(_compactMode ? "mb-1" : "mb-3")">
                            This is how your content will look with the current settings.
                            The theme, font size, and compact mode are reflected here.
                        </p>
                        <div class="d-flex gap-2 @(_compactMode ? "mb-1" : "mb-3")">
                            <button class="btn btn-sm btn-primary" style="@GetPreviewFontStyle()">Primary</button>
                            <button class="btn btn-sm btn-secondary" style="@GetPreviewFontStyle()">Secondary</button>
                        </div>
                        <ul class="@(_compactMode ? "mb-0 ps-3" : "")" style="@GetPreviewFontStyle()">
                            <li>List item one</li>
                            <li>List item two</li>
                            <li>List item three</li>
                        </ul>
                        <div class="mt-2 small text-muted">
                            Language: @_language &middot; @_fontSize &middot; @(_compactMode ? "Compact" : "Normal")
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <button class="btn btn-primary mt-3" @onclick="Save" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired]
    public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _saving;
    private string? _statusMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var bg = _theme switch
        {
            "Dark" => "bg-dark text-light",
            "System" => "bg-body-secondary",
            _ => "bg-white"
        };
        return $"{bg} rounded border";
    }

    private string GetPreviewStyles()
    {
        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1rem;";
        return $"transition: all 0.3s ease; {padding}";
    }

    private string GetPreviewFontStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "font-size: 0.8rem;",
            "Large" => "font-size: 1.15rem;",
            _ => "font-size: 0.95rem;"
        };
        return size;
    }

    private async Task Save()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _statusMessage = "Appearance settings saved!";
        _saving = false;
    }
}

@page "/settings"
@namespace sv_e0a9608232cf4e858fc3679f81403fff.Components.Pages.Settings
@using sv_e0a9608232cf4e858fc3679f81403fff.Models
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <div class="settings-nav">
        <SettingsSidebar ActiveSection="@_activeSection"
                         OnSectionChanged="section => _activeSection = section" />
    </div>
    <div class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "profile";
}

.settings-layout {
    display: flex;
    gap: 1.5rem;
    min-height: 70vh;
}

.settings-nav {
    flex: 0 0 220px;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

::deep .settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0.375rem;
    padding: 0.5rem 1rem;
    margin-bottom: 0.125rem;
    transition: background-color 0.15s ease;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #f0f0f0;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

@media (max-width: 768px) {
    .settings-layout {
        flex-direction: column;
    }

    .settings-nav {
        flex: none;
    }
}

